import React from 'react';

export default function Button({ children, onClick }) {
  return <button onClick={onClick}>{children}</button>;
}

package com.app;

import java.util.List;

public class OrderService {

    private static final double TAX_RATE = 0.08;

    public double calculateTotal(List<Double> itemPrices) {
        double subtotal = itemPrices.stream().mapToDouble(Double::doubleValue).sum();
        return subtotal + (subtotal * TAX_RATE);
    }

    public boolean isValidOrder(List<Double> itemPrices) {
        return itemPrices != null && !itemPrices.isEmpty();
    }
}

