import React from 'react';

export default function Spinner({ size = 20 }) {
  return (
    <span
      style={{ width: size, height: size, borderRadius: '50%', border: '2px solid var(--studio-border, #d8d1c5)', borderTopColor: 'var(--studio-accent, #c15f3c)' }}
    />
  );
}

function useProjectSummary(projectId) {
  const [summary, setSummary] = useState(null);
  useEffect(() => {
    if (!projectId) return;
    fetch(`/api/projects/${projectId}/summary`)
      .then(res => res.json())
      .then(setSummary)
      .catch(console.error);
  }, [projectId]);
  return summary;
}

func (h *WidgetsHandler) HandleListWidgets(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	widgets, err := h.db.ListWidgets()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(map[string]any{"widgets": widgets})
}

