import React from 'react';

export default function UserProfile({ user }) {
  if (!user) return null;

  return (
    <div style={{ display: 'flex', gap: 16, padding: 16, border: '1px solid #e2dcd4', borderRadius: 8 }}>
      <img
        src={user.avatarUrl}
        alt={user.name}
        style={{ width: 64, height: 64, borderRadius: '50%', objectFit: 'cover' }}
      />
      <div>
        <h3 style={{ margin: '0 0 4px' }}>{user.name}</h3>
        <p style={{ margin: 0, color: '#746b63', fontSize: 13 }}>{user.bio || 'No bio provided.'}</p>
      </div>
    </div>
  );
}
